}
catch (const std::bad_alloc &)
```

Your task is to implement the function `readFromFileStream` with the following signature:

```cpp
ULONG readFromFileStream(void* _pv, ULONG _cb);
```

Where:
- `_pv`: A pointer to the buffer where the data should be read.
- `_cb`: The number of bytes to read from the file stream.

Your function should read `_cb` bytes from the file stream into the buffer pointed to by `_pv`. If the read operation is successful, the function should return the number of bytes actually read. If an exception of type `std::ios_base::failure` occurs during the read operation, the function should return the error code `STG_E_ACCESSDENIED`. If an exception of type `std::bad_alloc` occurs during the read operation, the function should return the error code `STG_E_OUTOFMEMORY`.

Assume that the file stream `mRstream` is a member variable of the class containing the `readFromFileStream` function.

```cpp
ULONG readFromFileStream(void* _pv, ULONG _cb) {
    try {
        this->mRstream.read(static_cast<char *>(_pv), _cb);
        return static_cast<ULONG>(this->mRstream.gcount());
    }
    catch (const std::ios_base::failure &) {
        return STG_E_ACCESSDENIED;
    }
    catch (const std::bad_alloc &) {
        return STG_E_OUTOFMEMORY;
    }
}
```

The `readFromFileStream` function attempts to read `_cb` bytes from the file stream into the buffer pointed to by `_pv`. If the read operation is successful, it returns the number of bytes actually read. If an exception of type `std::ios_base::failure` occurs, it returns the error code `STG_E_ACCESSDENIED`. If an exception of type `std::bad_alloc` occurs, it returns the error code `STG_E_OUTOFMEMORY`.

```cpp
#include <iostream>

class BankAccount {
private:
    double balance;
    const double minBalance = 100;

public:
    BankAccount(double initialBalance) : balance(initialBalance) {}

    void deposit(double amount) {
        balance += amount;
    }

    bool withdraw(double amount) {
        if (balance - amount >= minBalance) {
            balance -= amount;
            return true;
        } else {
            std::cout << "Withdrawal rejected. Insufficient balance." << std::endl;
            return false;
        }
    }

    double getBalance() const {
        return balance;
    }
};

int main() {
    BankAccount account(500);  // Create an account with initial balance of 500
    std::cout << "Initial balance: " << account.getBalance() << std::endl;

    account.deposit(300);  // Deposit 300
    std::cout << "Balance after deposit: " << account.getBalance() << std::endl;

    if (account.withdraw(400)) {  // Withdraw 400
        std::cout << "Balance after withdrawal: " << account.getBalance() << std::endl;
    }

    if (account.withdraw(600)) {  // Attempt to withdraw 600 (rejected)
        std::cout << "Balance after withdrawal: " << account.getBalance() << std::endl;
    }

    return 0;
}
```

