You are tasked with implementing a simple thread pool in C++. A thread pool is a collection of threads that can be used to execute tasks concurrently. The main goal of a thread pool is to limit the number of threads that are created, as creating and destroying threads can be an expensive operation. The thread pool should be able to accept tasks and execute them using a fixed number of worker threads.

Your task is to implement the `ThreadPool` class with the following specifications:
- The `ThreadPool` class should have a constructor that takes an integer parameter `numThreads` representing the number of worker threads in the pool.
- The `ThreadPool` class should have a method `submit` that takes a function or callable object and adds it to the task queue to be executed by one of the worker threads.
- The `ThreadPool` class should have a method `shutdown` that stops all worker threads and prevents the submission of any new tasks.

You should use the provided code snippet as a starting point and implement the missing parts of the `ThreadPool` class.

```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <functional>
#include <mutex>
#include <condition_variable>

class ThreadPool {
public:
    ThreadPool(int numThreads) : numThreads_(numThreads), stop_(false) {
        for (int i = 0; i < numThreads_; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex_);
                        condition_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                        if (stop_ && tasks_.empty()) {
                            return;
                        }
                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }
                    task();
                }
            });
        }
    }

    template <class F>
    void submit(F&& f) {
        {
            std::unique_lock<std::mutex> lock(queueMutex_);
            tasks_.emplace(std::forward<F>(f));
        }
        condition_.notify_one();
    }

    void shutdown() {
        {
            std::unique_lock<std::mutex> lock(queueMutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    virtual ~ThreadPool() {
        shutdown();
    }

private:
    int numThreads_;
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex queueMutex_;
    std::condition_variable condition_;
    bool stop_;
};

int main() {
    ThreadPool pool(4);

    for (int i = 0; i < 8; ++i) {
        pool.submit([i] {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::cout << "Task " << i << " executed by thread " << std::this_thread::get_id() << std::endl;
        });
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));

    pool.shutdown();

    return 0;
}
