```cpp
#include <iostream>
#include <vector>

struct I2Point {
    int x, y;
};

namespace nvector {
    template <typename T>
    std::vector<T> Read(int n) {
        std::vector<T> vec(n);
        for (int i = 0; i < n; ++i) {
            std::cin >> vec[i].x >> vec[i].y;
        }
        return vec;
    }
}

bool CheckCollinear(const I2Point& p1, const I2Point& p2, const I2Point& p3) {
    return (p2.y - p1.y) * (p3.x - p2.x) == (p3.y - p2.y) * (p2.x - p1.x);
}

