    auto vp = nvector::Read<I2Point>(3);
    bool b = false;
    for (unsigned i = 0; i < 3; ++i) {
        if (i < 2) {
            b = CheckCollinear(vp[i], vp[i + 1], vp[i + 2]);
            if (!b) {
                break;
            }
        }
    }
    std::cout << "Points are collinear: " << std::boolalpha << b << std::endl;
    return 0;
}
