You need to implement the `PriorityQueue` class with the following member functions:
```cpp
class PriorityQueue {
public:
    PriorityQueue();  // Constructor to initialize an empty priority queue
    ~PriorityQueue(); // Destructor to free memory allocated for the priority queue

    void enqueue(int value, int priority); // Add a new element with the given value and priority
    int dequeue(); // Remove and return the element with the highest priority
    bool isEmpty(); // Return true if the priority queue is empty, false otherwise
};
```

You should use the provided `Node` structure to implement the priority queue. The priority queue should be implemented using a singly linked list, and elements should be ordered based on their priority, with higher priority elements being dequeued first.

```cpp
#include <iostream>

struct Node {
    int value;
    int priority;
    Node* next;
};

class PriorityQueue {
private:
    Node* head;

public:
    PriorityQueue() : head(nullptr) {}

    ~PriorityQueue() {
        while (head != nullptr) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void enqueue(int value, int priority) {
        Node* newNode = new Node{value, priority, nullptr};
        if (head == nullptr || priority > head->priority) {
            newNode->next = head;
            head = newNode;
        } else {
            Node* current = head;
            while (current->next != nullptr && current->next->priority >= priority) {
                current = current->next;
            }
            newNode->next = current->next;
            current->next = newNode;
        }
    }

    int dequeue() {
        if (isEmpty()) {
            std::cerr << "Error: Queue is empty" << std::endl;
            return -1; // Assuming -1 as an error value
        }
        Node* temp = head;
        int value = head->value;
        head = head->next;
        delete temp;
        return value;
    }

    bool isEmpty() {
        return head == nullptr;
    }
};

int main() {
    PriorityQueue pq;
    pq.enqueue(10, 2);
    pq.enqueue(20, 1);
    pq.enqueue(30, 3);

    while (!pq.isEmpty()) {
        std::cout << pq.dequeue() << " ";
    }
    // Output: 30 10 20
    return 0;
}
```

