```cpp
#include <iostream>
#include <vector>
#include <functional>
#include <mutex>
#include <thread>

using namespace std;

class DiningPhilosophers {
public:
    DiningPhilosophers(int num) : m_(num) {}

    void wantsToEat(int philosopher, function<void()> pickLeftFork, function<void()> pickRightFork, function<void()> eat, function<void()> putLeftFork, function<void()> putRightFork) {
        int left = philosopher;
        int right = (philosopher + 1) % m_.size();

        if (philosopher % 2 == 0) {
            m_[left].lock();
            pickLeftFork();
            m_[right].lock();
            pickRightFork();
            eat();
            putRightFork();
            m_[right].unlock();
            putLeftFork();
            m_[left].unlock();
        } else {
            m_[right].lock();
            pickRightFork();
            m_[left].lock();
            pickLeftFork();
            eat();
            putLeftFork();
            m_[left].unlock();
            putRightFork();
            m_[right].unlock();
        }
    }

private:
    vector<mutex> m_;
};
