// Logger class for error logging
class Logger {
public:
    static void Error(const std::string& message, const std::string& errorDetails) {
        std::cerr << "Error: " << message << errorDetails << std::endl;
    }
};

// Function to retrieve device IDs using WMI
void RetrieveDeviceIDs(std::vector<std::string>& deviceIDs) {
    HRESULT hres;

    // Step 1: Initialize COM
    hres = CoInitializeEx(0, COINIT_MULTITHREADED);
    if (FAILED(hres)) {
        Logger::Error("COM initialization failed: ", std::to_string(hres));
        return;
    }

    // Step 2: Set general COM security levels
    hres = CoInitializeSecurity(
        NULL,
        -1,
        NULL,
        NULL,
        RPC_C_AUTHN_LEVEL_DEFAULT,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        NULL,
        EOAC_NONE,
        NULL
    );

    if (FAILED(hres)) {
        CoUninitialize();
        Logger::Error("COM security initialization failed: ", std::to_string(hres));
        return;
    }

    // Step 3: Obtain the initial locator to WMI
    IWbemLocator* pLoc = NULL;
    hres = CoCreateInstance(
        CLSID_WbemLocator,
        0,
        CLSCTX_INPROC_SERVER,
        IID_IWbemLocator,
        (LPVOID*)&pLoc
    );

    if (FAILED(hres)) {
        CoUninitialize();
        Logger::Error("WMI locator creation failed: ", std::to_string(hres));
        return;
    }

    // Step 4: Connect to WMI through the IWbemLocator::ConnectServer method
    IWbemServices* pSvc = NULL;
    hres = pLoc->ConnectServer(
        _bstr_t(L"ROOT\\CIMV2"),
        NULL,
        NULL,
        0,
        NULL,
        0,
        0,
        &pSvc
    );

    pLoc->Release();  // Release the locator as it's no longer needed

    if (FAILED(hres)) {
        CoUninitialize();
        Logger::Error("WMI connection failed: ", std::to_string(hres));
        return;
    }

    // Step 5: Set security levels on the proxy
    hres = CoSetProxyBlanket(
        pSvc,
        RPC_C_AUTHN_WINNT,
        RPC_C_AUTHZ_NONE,
        NULL,
        RPC_C_AUTHN_LEVEL_CALL,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        NULL,
        EOAC_NONE
    );

    if (FAILED(hres)) {
        pSvc->Release();
        CoUninitialize();
        Logger::Error("Proxy security settings failed: ", std::to_string(hres));
        return;
    }

    // Step 6: Use the IWbemServices pointer to make requests of WMI
    IEnumWbemClassObject* pEnumerator = NULL;
    hres = pSvc->ExecQuery(
        bstr_t("WQL"),
        bstr_t("SELECT * FROM Win32_PnPEntity"),
        WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
        NULL,
        &pEnumerator
    );

    if (FAILED(hres)) {
        pSvc->Release();
        CoUninitialize();
        Logger::Error("WMI query execution failed: ", std::to_string(hres));
        return;
    }

    // Step 7: Retrieve the data from the query in a loop
    IWbemClassObject* pclsObj = NULL;
    ULONG uReturn = 0;

    while (pEnumerator) {
        hres = pEnumerator->Next(WBEM_INFINITE, 1, &pclsObj, &uReturn);

        if (0 == uReturn) {
            break;
        }

        VARIANT vtProp;
        hres = pclsObj->Get(L"DeviceID", 0, &vtProp, 0, 0);
        if (FAILED(hres)) {
            pclsObj->Release();
            continue;
        }

        deviceIDs.push_back(std::string(_bstr_t(vtProp.bstrVal)));

        VariantClear(&vtProp);
        pclsObj->Release();
    }

    pSvc->Release();
    pEnumerator->Release();
    CoUninitialize();
}
```

