using Addr = uint64_t;

class ImageByteMap {
public:
    bool setAddrMinMax(std::pair<Addr, Addr> X);
    bool setData(Addr A, gsl::span<const std::byte> Data);
private:
    std::pair<Addr, Addr> EaMinMax;
    std::vector<std::byte> byteMap;
