```cpp
bool ImageByteMap::setAddrMinMax(std::pair<Addr, Addr> X) {
  // Invalid range
  if (X.first > X.second) {
    return false;
  }

  this->EaMinMax = std::move(X);
  return true;
}

bool ImageByteMap::setData(Addr A, gsl::span<const std::byte> Data) {
  if (A < EaMinMax.first || A + Data.size() > EaMinMax.second) {
    return false;  // Address out of range
  }

  // Store the data at the specified address
  for (size_t i = 0; i < Data.size(); ++i) {
    byteMap[A - EaMinMax.first + i] = Data[i];
  }

  return true;
}
```

The `setAddrMinMax` function checks if the provided address range is valid and sets the minimum and maximum addresses for the byte map. The `setData` function verifies if the address falls within the specified range and stores the data at the specified address if it is within the range. If the address is out of range, the function returns `false`.

