#include <iostream>
#include <fstream>
#include <vector>
#include <tuple>
#include "llvm/Object/ELFObjectFile.h"
#include "llvm/Object/ObjectFile.h"
#include "llvm/Support/TargetSelect.h"
#include "llvm/Support/FileSystem.h"
#include "llvm/Support/raw_ostream.h"

std::vector<std::tuple<std::string, std::string, size_t>> analyzeELFFile(const std::string& filePath) {
    llvm::InitializeAllTargetInfos();
    llvm::InitializeAllTargetMCs();
    llvm::InitializeAllAsmParsers();
    llvm::InitializeAllDisassemblers();

    std::vector<std::tuple<std::string, std::string, size_t>> globalVariables;

    llvm::ErrorOr<std::unique_ptr<llvm::MemoryBuffer>> fileOrErr = llvm::MemoryBuffer::getFile(filePath);
    if (std::error_code ec = fileOrErr.getError()) {
        llvm::errs() << "Error reading file: " << ec.message() << "\n";
        return globalVariables;
    }

    llvm::Expected<std::unique_ptr<llvm::object::Binary>> binaryOrErr = llvm::object::createBinary(fileOrErr.get()->getMemBufferRef());
    if (!binaryOrErr) {
        llvm::errs() << "Error parsing binary: " << llvm::toString(binaryOrErr.takeError()) << "\n";
        return globalVariables;
    }

    llvm::object::ELFObjectFile<llvm::object::ELF64LE> *elfObject = dyn_cast<llvm::object::ELFObjectFile<llvm::object::ELF64LE>>(binaryOrErr.get().get());
    if (!elfObject) {
        llvm::errs() << "Error casting to ELFObjectFile\n";
        return globalVariables;
    }

    for (auto &symbol : elfObject->symbols()) {
        if (symbol.getFlags() & llvm::object::SymbolRef::SF_Global) {
            llvm::StringRef name;
            if (auto nameOrErr = symbol.getName())
                name = *nameOrErr;
            else
                continue;

            llvm::object::section_iterator section = symbol.getSection();
            if (section == elfObject->section_end())
                continue;

            llvm::StringRef typeName;
            llvm::object::section_iterator sectionEnd = elfObject->section_end();
            for (auto &section : elfObject->sections()) {
                if (section.getName() == ".debug_info") {
                    llvm::Expected<llvm::DWARFDataExtractor> extractor = section.getRelocatedSection().getDWARFStreamer();
                    if (extractor) {
                        llvm::DWARFDataExtractor &dataExtractor = *extractor;
                        uint64_t offset = symbol.getValue();
                        llvm::dwarf::Tag tag;
                        llvm::StringRef typeString;
                        if (dataExtractor.getTagTypeAndName(offset, tag, typeString)) {
                            typeName = typeString;
                            break;
                        }
                    }
                }
            }

            llvm::DataLayout dataLayout = elfObject->getDataLayout();
            uint64_t size = 0;
            if (auto sizeOrErr = symbol.getSize())
                size = *sizeOrErr;

            globalVariables.emplace_back(name.str(), typeName.str(), size);
        }
    }

    return globalVariables;
}

int main() {
    std::string filePath = "path_to_your_elf_file";
    std::vector<std::tuple<std::string, std::string, size_t>> result = analyzeELFFile(filePath);
    for (const auto& variable : result) {
        std::cout << std::get<0>(variable) << " : " << std::get<1>(variable) << " : " << std::get<2>(variable) << " bytes\n";
    }
    return 0;
}
```

