```cpp
void unique(std::vector<int>& v) {
    if (v.size() < 2) {
        return;  // No consecutive duplicates possible
    }

    auto it = v.begin();
    while (it != v.end() - 1) {
        if (*it == *(it + 1)) {
            it = v.erase(it);  // Remove consecutive duplicate
        } else {
            ++it;
        }
    }
}
```

