                utf8String += 2;
            }
        } else if ((*utf8String & 0xF8) == 0xF0) {
            // Four-byte code point
            if (isContinuationByte(*(utf8String + 1)) && isContinuationByte(*(utf8String + 2)) && isContinuationByte(*(utf8String + 3))) {
                clusters++;
                utf8String += 3;
            }
        }
        utf8String++;
    }
    return clusters;
}
```

