#include <iostream>

struct Color {
    float r, g, b;
};

Color blendColors(int illuminationType, Color c1, Color c2, Color c3) {
    if (illuminationType == 0) {
        // Flat shading: average of the three input colors
        Color blendedColor;
        blendedColor.r = (c1.r + c2.r + c3.r) / 3.0f;
        blendedColor.g = (c1.g + c2.g + c3.g) / 3.0f;
        blendedColor.b = (c1.b + c2.b + c3.b) / 3.0f;
        return blendedColor;
    } else if (illuminationType == 1) {
        // Gouraud shading: weighted average based on light intensity
        // Assuming light intensity is represented by the color components themselves
        Color blendedColor;
        float totalIntensity = c1.r + c2.r + c3.r;
        blendedColor.r = (c1.r * c1.r + c2.r * c2.r + c3.r * c3.r) / totalIntensity;
        blendedColor.g = (c1.g * c1.g + c2.g * c2.g + c3.g * c3.g) / totalIntensity;
        blendedColor.b = (c1.b * c1.b + c2.b * c2.b + c3.b * c3.b) / totalIntensity;
        return blendedColor;
    } else {
        // Handle invalid illumination type
        std::cerr << "Invalid illumination type: " << illuminationType << std::endl;
        // Return a default color (e.g., black) in case of error
        return {0.0f, 0.0f, 0.0f};
    }
}

