void calculateOffsets(const std::vector<int>& verticesPerCurve, GA_OffsetList& offsets) {
    offsets.reserve(verticesPerCurve.size()); // Reserve space for the offsets list

    int cumulativeOffset = 0; // Initialize cumulative offset to 0

    for (int vertices : verticesPerCurve) {
        offsets.append(cumulativeOffset); // Add the cumulative offset for the current curve
