#include <iostream>
#include <list>
#include <utility>

class HashTable {
private:
    static const int tableSize = 10;
    std::list<std::pair<int, int>> table[tableSize];

    int hashFunction(int key) {
        return key % tableSize;
    }

public:
    void insert(int key, int value) {
        int index = hashFunction(key);
        for (auto& pair : table[index]) {
            if (pair.first == key) {
                std::cerr << "Key already exists. Use update instead of insert." << std::endl;
                return;
            }
        }
        table[index].emplace_back(key, value);
    }

    int retrieve(int key) {
        int index = hashFunction(key);
        for (auto& pair : table[index]) {
            if (pair.first == key) {
                return pair.second;
            }
        }
        std::cerr << "Key not found." << std::endl;
        return -1;  // Assuming -1 represents key not found
    }

    void remove(int key) {
        int index = hashFunction(key);
        for (auto it = table[index].begin(); it != table[index].end(); ++it) {
            if (it->first == key) {
                table[index].erase(it);
                return;
            }
        }
        std::cerr << "Key not found. No deletion performed." << std::endl;
    }
};

int main() {
    HashTable ht;
    ht.insert(5, 10);
    ht.insert(15, 20);
    std::cout << ht.retrieve(5) << std::endl;  // Output: 10
    std::cout << ht.retrieve(15) << std::endl;  // Output: 20
    ht.remove(5);
    std::cout << ht.retrieve(5) << std::endl;  // Output: Key not found.
    return 0;
}
