```cpp
#include <iostream>
#include <vector>

class QObject {
private:
    std::vector<void (*)()> connections;

public:
    // Connects a signal to a slot
    void connect(void (*signal)(), void (*slot)()) {
        if (signal != nullptr && slot != nullptr) {
            connections.push_back(slot);
        }
    }

    // Emits the signal, triggering the connected slots
    void emit(void (*signal)()) {
        for (auto& slot : connections) {
            if (signal == slot) {
                slot();
            }
        }
    }
};

void authSignal() {
    std::cout << "Auth signal emitted" << std::endl;
}

void authSlot() {
    std::cout << "Auth slot called" << std::endl;
}

int main() {
    QObject obj;
    obj.connect(authSignal, authSlot);
    // Trigger the auth signal, which should call the auth slot
    obj.emit(authSignal);
    return 0;
}
```

In the solution, the `QObject` class maintains a vector of connected slots. When the `connect` method is called, it adds the provided slot to the list of connections. The `emit` method iterates through the connections and calls the slots that match the emitted signal. When the `authSignal` is emitted, the `authSlot` is called as a result of the connection established earlier.

