class DynamicLibraryLoader {
private:
    HMODULE dll_;

public:
    DynamicLibraryLoader(const char* dllPath) {
        dll_ = LoadLibrary(dllPath);
        if (dll_ == NULL) {
            std::cerr << "Failed to load the DLL" << std::endl;
            // Handle error, throw exception, or exit
        }
    }

    template <typename T>
    T getFunction(const char* functionName) {
        T functionPtr = reinterpret_cast<T>(GetProcAddress(dll_, functionName));
        if (functionPtr == NULL) {
            std::cerr << "Failed to retrieve function pointer for " << functionName << std::endl;
            // Handle error, throw exception, or exit
        }
        return functionPtr;
    }

    ~DynamicLibraryLoader() {
        if (dll_ != NULL) {
            FreeLibrary(dll_);
        }
    }
};

int main() {
