    StartHookProc startApi = loader.getFunction<StartHookProc>(HOOK_DLL_START_HOOK);
    StopHookProc stopApi = loader.getFunction<StopHookProc>(HOOK_DLL_STOP_HOOK);

    if (startApi && stopApi) {
        // Call the functions from the loaded DLL
