#include <type_traits>

namespace srook {

template <typename T>
struct is_predecrementable {
    private:
        template <typename U>
        static auto test(U* u) -> decltype(--(*u), std::true_type{});
        static std::false_type test(...);

    public:
        static constexpr bool value = decltype(test(static_cast<T*>(nullptr)))::value;
};

template <typename T>
struct is_nothrow_predecrementable {
    private:
        template <typename U>
        static auto test(U* u) -> decltype(--(*u), std::integral_constant<bool, noexcept(--(*u))>{});
        static std::false_type test(...);

    public:
        static constexpr bool value = decltype(test(static_cast<T*>(nullptr)))::value;
};

} // namespace srook
```

In the solution, the `is_predecrementable` and `is_nothrow_predecrementable` type traits are implemented using SFINAE (Substitution Failure Is Not An Error) technique. The `test` function is used to check if the pre-decrement operation is valid for the given type. If the operation is valid, the `value` is set to `true`, and for `is_nothrow_predecrementable`, it additionally checks if the operation is non-throwing using `noexcept`.

