// Function to calculate the Fibonacci sequence up to a certain index
void calculateFibonacci(vector<long long>& fib, int n) {
    fib[0] = 0;
    fib[1] = 1;
    for (int i = 2; i <= n; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
}

// Function to determine the flower order based on Fibonacci numbers
string flowerOrder(int n, long long k) {
    vector<long long> fib(n + 3);
    calculateFibonacci(fib, n + 2);

    if (k > fib[n + 2]) {
        return "Flowers";
    } else {
        long long order = k;
        for (int i = n + 2; i >= 3; --i) {
            if (order > fib[i - 2]) {
                order -= fib[i - 2];
            } else if (order > 1) {
                order--;
            } else {
                return (i == n + 2) ? "Lilies" : "Roses";
            }
        }
    }
    return "Roses";
}

int main() {
    int n;
    long long k;
    cin >> n >> k;
    cout << flowerOrder(n, k) << endl;
    return 0;
}
