        }
        std::cout << std::endl;
    }

    diagonalSwap(matrix, n);

    std::cout << "Matrix after diagonal swap:" << std::endl;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << matrix[i][j] << " ";
        }
