You need to create a function that takes the `TriangleMesh` object as input and returns the average color of all the vertices in the mesh.

You can assume the following:
- The `TriangleMesh` class has a method `get_vertex_colors()` that returns a reference to the `ColorList` containing the vertex colors.
- The `ColorList` class has a method `size()` that returns the number of colors in the list, and a method `operator[]` that allows access to individual colors by index.
- Each color in the `ColorList` is represented as a 3-element array of integers, where each element represents the red, green, and blue components of the color, respectively.

Your task is to implement the function `calculate_average_color` that takes a `TriangleMesh` object as input and returns the average color of all the vertices in the mesh.

```cpp
#include <vector>

class TriangleMesh {
public:
    using Color = std::array<int, 3>;
    using ColorList = std::vector<Color>;

    const ColorList& get_vertex_colors() const {
        return vertex_colors_;
    }

private:
    ColorList vertex_colors_;
};

class ColorCalculator {
public:
    static TriangleMesh::Color calculate_average_color(const TriangleMesh& mesh) {
        const TriangleMesh::ColorList& colors = mesh.get_vertex_colors();
        int totalRed = 0, totalGreen = 0, totalBlue = 0;

        for (const auto& color : colors) {
            totalRed += color[0];
            totalGreen += color[1];
            totalBlue += color[2];
        }

        int numColors = colors.size();
        return {totalRed / numColors, totalGreen / numColors, totalBlue / numColors};
    }
};
```

