using key_pos_t = int;
using subkey_mask_t = std::bitset<64>; // Assuming a maximum of 64 positions

std::tuple<std::vector<key_pos_t>, std::vector<key_pos_t>, subkey_mask_t> updateMappings(
    const std::vector<key_pos_t>& key_to_subkey,
    const std::vector<key_pos_t>& subkey_to_key,
    const subkey_mask_t& removed_positions,
    const std::vector<std::tuple<std::string, key_pos_t>>& operations) {

    std::vector<key_pos_t> updated_key_to_subkey = key_to_subkey;
    std::vector<key_pos_t> updated_subkey_to_key = subkey_to_key;
    subkey_mask_t updated_removed_positions = removed_positions;

    for (const auto& op : operations) {
        const std::string& type = std::get<0>(op);
        const key_pos_t& position = std::get<1>(op);

        if (type == "add") {
            updated_key_to_subkey.push_back(position);
            updated_subkey_to_key.push_back(position);
            updated_removed_positions.reset(position);
        } else if (type == "remove") {
            updated_key_to_subkey.erase(std::remove(updated_key_to_subkey.begin(), updated_key_to_subkey.end(), position), updated_key_to_subkey.end());
            updated_subkey_to_key.erase(std::remove(updated_subkey_to_key.begin(), updated_subkey_to_key.end(), position), updated_subkey_to_key.end());
            updated_removed_positions.set(position);
        }
    }

    return std::make_tuple(updated_key_to_subkey, updated_subkey_to_key, updated_removed_positions);
}
```

The `updateMappings` function iterates through the given operations and updates the mappings and removed positions based on the operation type and position. It uses standard vector operations to add or remove positions from the mappings and sets or resets the corresponding bit in the removed positions bit vector. The function returns the updated `key_to_subkey`, `subkey_to_key`, and `removed_positions` as a tuple.

