class KAryTree {
  using TreePtr = std::unique_ptr<KAryTree>;

 private:
  int value;
  std::vector<TreePtr> children;

 public:
  KAryTree(int val) : value(val) {}

  void insert(int parentValue, int val) {
    TreePtr newNode = std::make_unique<KAryTree>(val);
    insertHelper(this, parentValue, std::move(newNode));
  }

  void insertHelper(KAryTree* node, int parentValue, TreePtr newNode) {
    if (node->value == parentValue) {
      node->children.push_back(std::move(newNode));
      return;
    }
    for (auto& child : node->children) {
      insertHelper(child.get(), parentValue, std::move(newNode));
    }
  }

  void preOrderTraversalHelper(KAryTree* node, std::vector<int>& result) {
    if (node == nullptr) {
      return;
    }
    result.push_back(node->value);
    for (auto& child : node->children) {
      preOrderTraversalHelper(child.get(), result);
    }
  }

  std::vector<int> preOrderTraversal() {
    std::vector<int> result;
    preOrderTraversalHelper(this, result);
    return result;
  }

  void inOrderTraversalHelper(KAryTree* node, std::vector<int>& result) {
    if (node == nullptr) {
      return;
    }
    if (!node->children.empty()) {
      inOrderTraversalHelper(node->children[0].get(), result);
    }
    result.push_back(node->value);
    for (size_t i = 1; i < node->children.size(); ++i) {
      inOrderTraversalHelper(node->children[i].get(), result);
    }
  }

  std::vector<int> inOrderTraversal() {
    std::vector<int> result;
    inOrderTraversalHelper(this, result);
    return result;
  }

  void postOrderTraversalHelper(KAryTree* node, std::vector<int>& result) {
    if (node == nullptr) {
      return;
    }
    for (auto& child : node->children) {
      postOrderTraversalHelper(child.get(), result);
    }
    result.push_back(node->value);
