```cpp
#include <vector>
#include <omp.h>

std::vector<std::vector<float>> parallelMatrixOperation(const std::vector<std::vector<float>>& in, const std::vector<float>& alpha, const std::vector<float>& beta, int rows, int cols) {
    std::vector<std::vector<float>> out(rows, std::vector<float>(cols, 0.0f));

    #pragma omp parallel for
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            out[i][j] = alpha[j] * in[i][j] + (beta.empty() ? 0 : beta[j]);
        }
    }

    return out;
}
```

