template< typename TInputImage, typename TOutputImage >
class LabelVotingBinaryImageFilter : public ImageToImageFilter< TInputImage, TOutputImage >
{
public:
  ITK_DISALLOW_COPY_AND_ASSIGN(LabelVotingBinaryImageFilter);

  using Self = LabelVotingBinaryImageFilter;
  using Superclass = ImageToImageFilter< TInputImage, TOutputImage >;
  using Pointer = SmartPointer<Self>;
  using ConstPointer = SmartPointer<const Self>;

  itkNewMacro(Self);
  itkTypeMacro(LabelVotingBinaryImageFilter, ImageToImageFilter);

  using InputImageType = TInputImage;
  using OutputImageType = TOutputImage;
  using InputPixelType = typename InputImageType::PixelType;
  using OutputPixelType = typename OutputImageType::PixelType;

  static constexpr unsigned int InputImageDimension = TInputImage::ImageDimension;
  static constexpr unsigned int OutputImageDimension = TOutputImage::ImageDimension;

  void GenerateData() override
  {
    // Create neighborhood iterator
    using NeighborhoodIteratorType = ConstNeighborhoodIterator<InputImageType>;
    NeighborhoodIteratorType it(this->GetInput(), this->GetInput()->GetLargestPossibleRegion());

    // Create output image iterator
    using OutputIteratorType = ImageRegionIterator<OutputImageType>;
    OutputIteratorType outIt(this->GetOutput(), this->GetOutput()->GetLargestPossibleRegion());

    // Define the neighborhood size for label voting
    constexpr unsigned int NeighborhoodRadius = 1;

    // Iterate over the input image
    for (it.GoToBegin(), outIt.GoToBegin(); !it.IsAtEnd(); ++it, ++outIt)
    {
      // Get the neighborhood around the current pixel
      typename NeighborhoodIteratorType::RadiusType radius;
      radius.Fill(NeighborhoodRadius);
      it.SetRadius(radius);

      // Perform label voting based on the labels present in the neighborhood
      std::vector<InputPixelType> labels;
      for (it.GoToBeginOfLine(); !it.IsAtEndOfLine(); it.NextLine())
      {
        for (it.GoToBeginOfSlice(); !it.IsAtEndOfSlice(); it.NextSlice())
        {
          labels.clear();
          for (it.GoToBegin(); !it.IsAtEnd(); ++it)
          {
            labels.push_back(it.Get());
          }
          // Perform label voting by finding the most frequent label
          std::sort(labels.begin(), labels.end());
          auto mostFrequentLabel = std::max_element(labels.begin(), labels.end(),
                                                    [&labels](const InputPixelType & a, const InputPixelType & b) {
                                                      return std::count(labels.begin(), labels.end(), a) < std::count(labels.begin(), labels.end(), b);
                                                    });
          outIt.Set(*mostFrequentLabel);
          ++outIt;
        }
      }
    }
  }
};
```
