    return abs(p1.x - p2.x) + abs(p1.y - p2.y);
}

int main(int argc, char *argv[]) {
    int sources, receivers, mules, dimension;
    if (argc != 5) {
        std::cout << "Please try again and input sources, receivers, mules, dimension." << std::endl;
        return 0;
    } else {
        sources = std::atoi(argv[1]);
        receivers = std::atoi(argv[2]);
        mules = std::atoi(argv[3]);
        dimension = std::atoi(argv[4]);

        std::vector<Point> sourceCoordinates(sources);
        std::vector<Point> receiverCoordinates(receivers);
        std::vector<Point> muleCoordinates(mules);

        // Input source coordinates
        for (int i = 0; i < sources; i++) {
            std::cin >> sourceCoordinates[i].x >> sourceCoordinates[i].y;
        }

        // Input receiver coordinates
        for (int i = 0; i < receivers; i++) {
            std::cin >> receiverCoordinates[i].x >> receiverCoordinates[i].y;
        }

        // Input mule coordinates
        for (int i = 0; i < mules; i++) {
            std::cin >> muleCoordinates[i].x >> muleCoordinates[i].y;
        }

        int minDistance = 0;
        for (int i = 0; i < sources; i++) {
            int minSourceToReceiver = INT_MAX;
            for (int j = 0; j < receivers; j++) {
                int distance = calculateManhattanDistance(sourceCoordinates[i], receiverCoordinates[j]);
                minSourceToReceiver = std::min(minSourceToReceiver, distance);
            }
            minDistance += minSourceToReceiver;
        }

        for (int i = 0; i < mules; i++) {
            int minMuleToSourceReceiver = INT_MAX;
            for (int j = 0; j < sources; j++) {
                for (int k = 0; k < receivers; k++) {
                    int distance = calculateManhattanDistance(muleCoordinates[i], sourceCoordinates[j]) +
                                   calculateManhattanDistance(muleCoordinates[i], receiverCoordinates[k]);
                    minMuleToSourceReceiver = std::min(minMuleToSourceReceiver, distance);
                }
            }
            minDistance += minMuleToSourceReceiver;
        }

        std::cout << "Minimum distance traveled by the mules: " << minDistance << std::endl;
    }
    return 0;
}
