// Define the evaluation function to determine the score of a game state
int EvaluateGameState(GameState* state) {
    // Implement your evaluation logic here to assign a score to the game state
    // Consider factors such as the number of connected pieces, potential winning positions, etc.
    // Return a higher score if the state is favorable for the AI player and a lower score if it's favorable for the opponent.
}

// Implement the minimax algorithm with alpha-beta pruning
int Minimax(GameState* state, int depth, int alpha, int beta, bool maximizingPlayer) {
    if (depth == 0 || state->IsTerminal()) {
        return EvaluateGameState(state);
    }

    if (maximizingPlayer) {
        int maxEval = INT_MIN;
        for (auto move : state->GetPossibleMoves()) {
            state->ApplyMove(move);
            int eval = Minimax(state, depth - 1, alpha, beta, false);
            state->UndoMove(move);
            maxEval = std::max(maxEval, eval);
            alpha = std::max(alpha, eval);
            if (beta <= alpha) {
                break;  // Beta cutoff
            }
        }
        return maxEval;
    } else {
        int minEval = INT_MAX;
        for (auto move : state->GetPossibleMoves()) {
            state->ApplyMove(move);
            int eval = Minimax(state, depth - 1, alpha, beta, true);
            state->UndoMove(move);
            minEval = std::min(minEval, eval);
            beta = std::min(beta, eval);
            if (beta <= alpha) {
                break;  // Alpha cutoff
            }
        }
        return minEval;
    }
}

// Complete the AI move selection using minimax algorithm with alpha-beta pruning
Connect4Move* SelectBestMove(GameState* state, int depth) {
    Connect4Move* bestMove = nullptr;
    int bestScore = INT_MIN;
    int alpha = INT_MIN;
    int beta = INT_MAX;

    for (auto move : state->GetPossibleMoves()) {
        state->ApplyMove(move);
        int score = Minimax(state, depth, alpha, beta, false);
        state->UndoMove(move);
        if (score > bestScore) {
            bestScore = score;
            bestMove = move;
        }
    }

    return bestMove;
}
```

