    Reference(std::string* obj) : referenceCount(1), referredObject(obj) {}

    void grabReference() {
        referenceCount++;
    }

    void releaseReference() {
        referenceCount--;
        if (referenceCount == 0) {
            delete referredObject;
            delete this;
        }
    }

    ~Reference() {
        delete referredObject;
    }
};

int main() {
