std::pair<std::string, std::unordered_map<std::string, std::string>> parseAnnotations(const std::string& input) {
    std::pair<std::string, std::unordered_map<std::string, std::string>> result;

    // Extract URL using regex
    std::regex urlRegex("url\\(\"(.*?)\"\\)");
    std::smatch urlMatch;
    if (std::regex_search(input, urlMatch, urlRegex)) {
        result.first = urlMatch[1];
    }

    // Extract key-value pairs using regex
    std::regex keyValueRegex("annotations\\[\"(.*?)\"\\] = \"(.*?)\"");
    std::sregex_iterator iter(input.begin(), input.end(), keyValueRegex);
    std::sregex_iterator end;
    while (iter != end) {
        result.second[(*iter)[1]] = (*iter)[2];
        ++iter;
    }

    return result;
}

