void handleDataChunk(QNetworkReply *reply) {
    if (reply->error() != QNetworkReply::NoError) {
        qDebug() << "Error: " << reply->errorString();
        return;
    }

    QString fileName = "downloaded_file"; // Set the desired file name
    QFile file(fileName);
    if (!file.open(QIODevice::WriteOnly | QIODevice::Append)) {
        qDebug() << "Error: Unable to open file for writing";
        return;
    }

    qint64 availableSize = reply->bytesAvailable();
    if (availableSize > 0) {
        QByteArray data = reply->readAll();
        file.write(data);
    }

    qint64 currentSize = file.size();
    if (currentSize >= m_totalSize) {
        qDebug() << "File download complete";
        file.close();
    } else {
        qint64 nextRangeStart = m_size + m_limit;
        if (nextRangeStart < m_totalSize) {
            QString range = "bytes=%1-%2";
            int rangeRValue = nextRangeStart + m_limit;
            if (rangeRValue > m_totalSize)
                rangeRValue = m_totalSize;
            range = range.arg(nextRangeStart).arg(rangeRValue);
            QNetworkRequest nextRequest = networkRequest;
            nextRequest.setRawHeader("Range", range.toUtf8());
            QNetworkReply *nextReply = m_pNetworkManager->get(nextRequest);
            connect(nextReply, &QNetworkReply::readyRead, [=]() {
                handleDataChunk(nextReply);
            });
        }
    }
}
```
In the `handleDataChunk` function, the received data chunk is written to a file. If the file size reaches the total expected size, the download is considered complete. If not, the next range for downloading is calculated, and a new network request is made to download the next chunk. This process continues until the entire file is downloaded and saved.

