```cpp
#include <iostream>
using namespace std;

class CustomList {
private:
    struct Node {
        int data;
        Node* prev;
        Node* next;
        Node(int val) : data(val), prev(nullptr), next(nullptr) {}
    };
    Node* head;
    Node* tail;

public:
    CustomList() : head(nullptr), tail(nullptr) {}

    void push_back(int val) {
        Node* newNode = new Node(val);
        if (head == nullptr) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    }

    void pop_back() {
        if (tail != nullptr) {
            if (tail == head) {
                delete tail;
                head = nullptr;
                tail = nullptr;
            } else {
                Node* prevNode = tail->prev;
                prevNode->next = nullptr;
                delete tail;
                tail = prevNode;
            }
        }
    }

    void reverse() {
        Node* current = head;
        Node* temp = nullptr;
        while (current != nullptr) {
            temp = current->prev;
            current->prev = current->next;
            current->next = temp;
            current = current->prev;
        }
        if (temp != nullptr) {
            head = temp->prev;
        }
    }

    void print() {
        Node* current = head;
        while (current != nullptr) {
            cout << current->data << endl;
            current = current->next;
        }
    }
};

int main() {
    CustomList lint;
    lint.push_back(1);
    lint.push_back(2);
    lint.push_back(3);
    lint.print();
    lint.reverse();
    lint.print();
    return 0;
}
