#include <atomic>

int atomic_update(std::atomic<int>& barrier_ts_, int base_ts) {
    int ret = 0;
    if (base_ts < 0) {
        ret = OB_INVALID_ARGUMENT;
        TRANS_LOG(WARN, "invalid argument", KR(ret), K(base_ts));
    } else {
        int expected = barrier_ts_.load();
        while (!barrier_ts_.compare_exchange_weak(expected, base_ts)) {
            // If the value of barrier_ts_ has changed, update the expected value
            expected = barrier_ts_.load();
        }
    }
    return ret;
}
