#include <iostream>
#include <vector>
using namespace std;

class Graph {
    int V;
    vector<vector<int>> adj;

public:
    Graph(int V) {
        this->V = V;
        adj.resize(V + 1);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);  // Assuming undirected graph
    }

    int countPathsUtil(int u, int v, int k, vector<vector<int>>& dp) {
        if (k == 0) {
            if (u == v) return 1;
            else return 0;
        }

        if (dp[u][v] != -1) return dp[u][v];

        int count = 0;
        for (int i = 0; i < adj[u].size(); i++) {
            count += countPathsUtil(adj[u][i], v, k - 1, dp);
        }

        dp[u][v] = count;
        return count;
    }

    int countPaths(int n, int k) {
        vector<vector<int>> dp(n + 1, vector<int>(n + 1, -1));
        int totalPaths = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                totalPaths += countPathsUtil(i, j, k, dp);
            }
        }
        return totalPaths / 2;  // Divide by 2 to avoid counting each path twice (due to undirected graph)
    }
};

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    Graph g(n);
    for (int i = 1; i <= m; i++) {
        int u, v;
        cin >> u >> v;
        g.addEdge(u, v);
    }
    cout << g.countPaths(n, k) << endl;
    return 0;
}
