#include <iostream>

class PID {
private:
    double Kp_;
    double Ki_;
    double Kd_;
    double prev_error_;
    double integral_;

public:
    PID() : Kp_(0.0), Ki_(0.0), Kd_(0.0), prev_error_(0.0), integral_(0.0) {}

    ~PID() {}

    void Init(double Kp, double Ki, double Kd) {
        Kp_ = Kp;
        Ki_ = Ki;
        Kd_ = Kd;
        prev_error_ = 0.0;
        integral_ = 0.0;
    }

    double Calculate(double setpoint, double pv) {
        double error = setpoint - pv;
        integral_ += error;
        double derivative = error - prev_error_;
        prev_error_ = error;

        return Kp_ * error + Ki_ * integral_ + Kd_ * derivative;
    }
};

int main() {
