    pid_controller.Init(0.5, 0.1, 0.2);  // Initialize PID coefficients

    double setpoint = 10.0;
    double process_variable = 8.0;

    double control_output = pid_controller.Calculate(setpoint, process_variable);
    std::cout << "Control Output: " << control_output << std::endl;

    return 0;
}
