        std::lock_guard<std::mutex> lock(scheduleMutex);
        if (index < schedule.size()) {
            schedule[index] = false;
        }
    }

    bool allTasksCompleted() const {
        std::lock_guard<std::mutex> lock(scheduleMutex);
        for (bool task : schedule) {
            if (!task) {
                return false;
            }
        }
        return true;
    }
};
