        if ((pos == 0 || !std::isalnum(lowerText[pos - 1])) && 
            (pos + lowerWord.length() == lowerText.length() || !std::isalnum(lowerText[pos + lowerWord.length()]))) {
            count++;
        }
        pos = lowerText.find(lowerWord, pos + 1);
    }

    return count;
}

