    if (dimension == 2) {
      if (calculateProjectionAngle(point) <= projection_angle_thresh) {
        if (xy_proj_safe) {
          if (isSafeForXYProjection(point)) {
            filteredIndices.push_back(index);
          }
        } else {
          filteredIndices.push_back(index);
        }
      }
    } else if (dimension == 3) {
      filteredIndices.push_back(index);
    }
  }
  return filteredIndices;
}
