#include <iostream>
#define ll long long
#define mod 1000000007

ll fact[1000001];
ll inv[1000001];

ll f(ll a, ll b) {
    if (b == 0) return 1;
    ll t = f(a, b / 2);
    t = (t * t) % mod;
    if (b % 2 == 0) return t;
    else return (a * t) % mod;
}

int modularInverse(int a, int mod) {
    fact[0] = 1;
    inv[0] = 1;
    for (ll i = 1; i < 1000001; ++i) {
        fact[i] = (i * fact[i - 1]) % mod;
        inv[i] = f(fact[i], mod - 2);
    }
    if (a >= mod) a %= mod;
    if (a == 0) return -1;  // Modular inverse does not exist
    return inv[a];
}

int main() {
    int n;
    std::cin >> n;
    std::cout << modularInverse(n, mod) << std::endl;
    return 0;
}
```

