#include <queue>
#include <memory>
#include <iostream>

// Event structure representing an event with a unique identifier and a timestamp
struct Event {
    int id;
    long long timestamp;
    // Other event properties and methods
    // ...
    void Delete() {
        // Implementation to delete the event
        std::cout << "Event " << id << " deleted." << std::endl;
    }
