#include <cstring>

class CustomString {
private:
    char* data;

public:
    CustomString() : data(nullptr) {}

    CustomString(const char* str) {
        size_t len = strlen(str);
        data = new char[len + 1];
        strcpy(data, str);
    }

    CustomString(const CustomString& other) {
        size_t len = other.length();
        data = new char[len + 1];
        strcpy(data, other.data);
    }

    ~CustomString() {
        delete[] data;
    }

    size_t length() const {
        return data ? strlen(data) : 0;
    }

    const char* c_str() const {
        return data ? data : "";
    }

    void append(const char* str) {
        size_t len1 = length();
        size_t len2 = strlen(str);
        char* newData = new char[len1 + len2 + 1];
        if (data) {
            strcpy(newData, data);
            delete[] data;
        }
        strcpy(newData + len1, str);
        data = newData;
    }

    void append(const CustomString& other) {
        append(other.c_str());
    }

    void clear() {
        delete[] data;
        data = nullptr;
    }

    CustomString& operator=(const CustomString& other) {
        if (this != &other) {
            clear();
            size_t len = other.length();
            data = new char[len + 1];
            strcpy(data, other.data);
        }
        return *this;
    }

    CustomString operator+(const CustomString& other) {
        CustomString result(*this);
        result.append(other);
        return result;
    }
};
