    double derivative = (offset - prevOffset) / timeDelta;

    if (derivative > threshold) {
        timeOverUsing += timeDelta;
        overuseCounter++;
    } else {
        timeOverUsing = std::max(0.0, timeOverUsing - timeDelta);
