You are tasked with implementing a simple linked list in C++. The linked list should support the following operations: 
1. Insert a new node at the beginning of the list.
2. Delete a node with a given value from the list.
3. Print the entire list.

You are given the following code snippet as a starting point:

```cpp
#include <iostream>

struct Node {
    int data;
    Node* next;
};

class LinkedList {
private:
    Node* head;

public:
    LinkedList() : head(nullptr) {}

    void insert(int value) {
        Node* newNode = new Node{value, head};
        head = newNode;
    }

    void remove(int value) {
        Node* current = head;
        Node* prev = nullptr;

        while (current != nullptr) {
            if (current->data == value) {
                if (prev == nullptr) {
                    head = current->next;
                } else {
                    prev->next = current->next;
                }
                delete current;
                break;
            }
            prev = current;
            current = current->next;
        }
    }

    void print() {
        Node* current = head;
        while (current != nullptr) {
            std::cout << current->data << " ";
            current = current->next;
        }
        std::cout << std::endl;
    }
};

int main() {
    LinkedList list;
    list.insert(3);
    list.insert(5);
    list.insert(7);
    list.print();

    list.remove(5);
    list.print();

    return 0;
}
```

