#include <iostream>
#include <unordered_map>
#include <stack>
#include <sstream>

class NamespaceManager {
private:
    std::unordered_map<std::string, NamespaceManager*> namespaces;
    std::stack<std::string> currentNamespace;

public:
    void createNamespace(const std::string& name) {
        namespaces[name] = new NamespaceManager();
    }

    void enterNamespace(const std::string& name) {
        if (namespaces.find(name) == namespaces.end()) {
            namespaces[name] = new NamespaceManager();
        }
        currentNamespace.push(name);
    }

    void exitNamespace() {
        if (!currentNamespace.empty()) {
            currentNamespace.pop();
        }
    }

    std::string getCurrentNamespace() {
        std::stack<std::string> tempStack = currentNamespace;
        std::stringstream ss;
        while (!tempStack.empty()) {
            ss << tempStack.top();
            tempStack.pop();
            if (!tempStack.empty()) {
                ss << "::";
            }
        }
        return ss.str();
    }

    void deleteNamespace(const std::string& name) {
        if (namespaces.find(name) != namespaces.end()) {
            delete namespaces[name];
            namespaces.erase(name);
        }
    }
};

int main() {
    NamespaceManager nsManager;
    nsManager.createNamespace("A");
    nsManager.enterNamespace("A");
    nsManager.createNamespace("B");
    nsManager.enterNamespace("B");
    nsManager.createNamespace("C");
    std::cout << nsManager.getCurrentNamespace() << std::endl;  // Output: "A::B::C"
    nsManager.exitNamespace();
    std::cout << nsManager.getCurrentNamespace() << std::endl;  // Output: "A::B"
    nsManager.deleteNamespace("B");
    std::cout << nsManager.getCurrentNamespace() << std::endl;  // Output: "A"
    return 0;
}
```

