You are tasked with implementing a simplified version of a memory management system. The system should support allocating and freeing memory blocks, and it should also be able to defragment the memory to ensure efficient memory usage.

You are given a class `MemoryManager` with the following methods:
- `allocate(size)`: This method should allocate a memory block of the given size and return a pointer to the allocated memory. If there is not enough contiguous free memory, it should return `nullptr`.
- `free(ptr)`: This method should free the memory block pointed to by `ptr`.
- `defragment()`: This method should defragment the memory by moving all allocated memory blocks to the beginning of the memory space, leaving the free memory as one contiguous block at the end.

You need to implement the `allocate`, `free`, and `defragment` methods of the `MemoryManager` class.

```cpp
#include <iostream>
#include <vector>

class MemoryManager {
private:
    std::vector<char> memory;
    std::vector<std::pair<size_t, size_t>> allocatedBlocks;

public:
    MemoryManager(size_t size) : memory(size, 0) {}

    char* allocate(size_t size) {
        for (size_t i = 0; i < memory.size(); ++i) {
            if (memory[i] == 0) {
                size_t j = i;
                while (j < memory.size() && memory[j] == 0 && j - i + 1 < size) {
                    ++j;
                }
                if (j - i + 1 == size) {
                    for (size_t k = i; k < j; ++k) {
                        memory[k] = 1;
                    }
                    allocatedBlocks.emplace_back(i, j - 1);
                    return &memory[i];
                }
                i = j;
            }
        }
        return nullptr;
    }

    void free(char* ptr) {
        size_t index = ptr - &memory[0];
        for (auto& block : allocatedBlocks) {
            if (block.first <= index && index <= block.second) {
                for (size_t i = block.first; i <= block.second; ++i) {
                    memory[i] = 0;
                }
                allocatedBlocks.erase(std::remove(allocatedBlocks.begin(), allocatedBlocks.end(), block), allocatedBlocks.end());
                break;
            }
        }
    }

    void defragment() {
        size_t freeIndex = 0;
        for (auto& block : allocatedBlocks) {
            size_t blockSize = block.second - block.first + 1;
            if (block.first != freeIndex) {
                for (size_t i = block.first; i <= block.second; ++i) {
                    memory[freeIndex] = memory[i];
                    memory[i] = 0;
                    ++freeIndex;
                }
                block.first = freeIndex - blockSize;
                block.second = freeIndex - 1;
            }
            freeIndex += blockSize;
        }
    }
};

int main() {
    MemoryManager manager(20);
    char* ptr1 = manager.allocate(5);
    char* ptr2 = manager.allocate(8);
    manager.free(ptr1);
    manager.defragment();
    char* ptr3 = manager.allocate(6);
    return 0;
}
```

