#include <zlib.h>
#include <folly/io/IOBuf.h>
#include <folly/io/Cursor.h>

class ZlibStreamCompressor {
public:
  ZlibStreamCompressor() {
    // Initialize Zlib stream
    memset(&stream_, 0, sizeof(stream_));
    deflateInit(&stream_, Z_DEFAULT_COMPRESSION);
  }

  ~ZlibStreamCompressor() {
    // Clean up Zlib stream
    deflateEnd(&stream_);
  }

  // Compress an IOBuf chain. Compress can be called multiple times and the
  // Zlib stream will be synced after each call. trailer must be set to
  // true on the final compression call.
  std::unique_ptr<folly::IOBuf> compress(const folly::IOBuf* in, bool trailer) {
    const folly::IOBuf* crtBuf = in;
    size_t offset = 0;
    int flush = (trailer) ? Z_FINISH : Z_NO_FLUSH;

    std::unique_ptr<folly::IOBuf> out = folly::IOBuf::create(FLAGS_zlib_compressor_buffer_growth);
    folly::io::Appender appender(out.get(), FLAGS_zlib_compressor_buffer_growth);

    while (crtBuf) {
      const folly::IOBuf* nextBuf = crtBuf->next();
      if (!nextBuf) {
        flush = (trailer) ? Z_FINISH : Z_SYNC_FLUSH;
      }

      while (crtBuf) {
        const uint8_t* data = crtBuf->data();
        size_t len = crtBuf->length();

        stream_.avail_in = len;
        stream_.next_in = const_cast<Bytef*>(data);

        do {
          out->unshare();
          stream_.avail_out = out->tailroom();
          stream_.next_out = out->writableTail();

          int ret = deflate(&stream_, flush);
          if (ret != Z_OK && ret != Z_STREAM_END) {
            throw std::runtime_error("Zlib compression error");
          }

          size_t written = out->tailroom() - stream_.avail_out;
          out->append(written);
        } while (stream_.avail_out == 0);

        offset += len;
        crtBuf = crtBuf->pop();
      }
      crtBuf = nextBuf;
    }

    if (trailer) {
      deflateReset(&stream_);
    }

    return out;
  }

private:
  z_stream stream_;
};
```

