vector<string> processWords(const string& s) {
    vector<string> result;
    int len = s.length();
    int i = 0;
    while (i < len) {
        if (!isalpha(s[i])) {
            i++;
            continue;
        }
        string word = "";
        int j = i;
        while (j < len) {
            if (isalpha(s[j])) {
                word += tolower(s[j]);
                j++;
            } else {
                if (s[j] == ',' || s[j] == '.' || s[j] == ':' || s[j] == ';' || s[j] == '!' || s[j] == '?' || s[j] == '\"') {
                    result.push_back(word);
                    break;
                }
                j++;
            }
        }
        i = j;
    }
    return result;
}

int main() {
