    ObjectType type;  // Type of the dynamic object
    void* data;       // Pointer to the data stored in the object
    bool isOwnerFlag; // Flag indicating ownership of allocated memory

public:
    // Constructor
    DynObject() : type(INTEGER), data(nullptr), isOwnerFlag(false) {}

