    DynObject& SetType(ObjectType type, void* data, bool isOwner) {
        this->type = type;
        this->data = data;
        this->isOwnerFlag = isOwner;
        return *this;
    }

    // Method to check if the object is the owner of the allocated memory
    bool IsOwner() const {
        return isOwnerFlag;
    }
};

