```cpp
#include <iostream>
#include <string>
#include <cctype>

int countWordOccurrences(const std::string& text, const std::string& word) {
    int count = 0;
    std::string lowerText = text;
    std::string lowerWord = word;

    // Convert both text and word to lowercase for case-insensitive comparison
    for (char& c : lowerText) {
        c = std::tolower(c);
    }
    for (char& c : lowerWord) {
        c = std::tolower(c);
    }

    // Find whole word matches and count occurrences
    size_t pos = lowerText.find(lowerWord, 0);
    while (pos != std::string::npos) {
        // Check if the match is a whole word
        if ((pos == 0 || !std::isalnum(lowerText[pos - 1])) && 
            (pos + lowerWord.length() == lowerText.length() || !std::isalnum(lowerText[pos + lowerWord.length()]))) {
            count++;
        }
        pos = lowerText.find(lowerWord, pos + 1);
    }

    return count;
}

int main() {
    std::string text = "The quick brown fox jumps over the lazy dog. The dog barks, but the fox keeps running.";
    std::string word = "the";
    std::cout << "Occurrences of '" << word << "': " << countWordOccurrences(text, word) << std::endl;
    return 0;
}
