    // Your implementation here
}
```

Function Signature:
```cpp
int maxFlow(int N, int S, int T, vector<vector<int>>& cap)
```

Input:
- N: an integer representing the number of nodes in the graph (2 ≤ N ≤ 100)
- S: an integer representing the source node (0 ≤ S < N)
- T: an integer representing the sink node (0 ≤ T < N, T ≠ S)
- cap: a 2D vector of integers representing the capacities of the edges in the graph. `cap[i][j]` indicates the capacity of the edge from node i to node j. (0 ≤ cap[i][j] ≤ 1000)

Output:
- An integer representing the maximum flow from the source node S to the sink node T.

Note:
- You can assume that the input graph is connected and that there is at least one path from the source to the sink.

```cpp
#include <vector>
#include <queue>
#include <algorithm>

int maxFlow(int N, int S, int T, vector<vector<int>>& cap) {
    int flow = 0;
    vector<vector<int>> residualCap = cap;
    vector<int> prev(N);

    while (true) {
        fill(prev.begin(), prev.end(), -1);
        queue<int> q;
        q.push(S);
        prev[S] = -2;

        while (!q.empty() && prev[T] == -1) {
            int u = q.front();
            q.pop();

            for (int v = 0; v < N; v++) {
                if (prev[v] == -1 && residualCap[u][v] > 0) {
                    q.push(v);
                    prev[v] = u;
                }
            }
        }

        if (prev[T] == -1) {
            break;
        }

        int pathFlow = INT_MAX;
        for (int v = T; v != S; v = prev[v]) {
            int u = prev[v];
            pathFlow = min(pathFlow, residualCap[u][v]);
        }

        for (int v = T; v != S; v = prev[v]) {
            int u = prev[v];
            residualCap[u][v] -= pathFlow;
            residualCap[v][u] += pathFlow;
        }

        flow += pathFlow;
    }

    return flow;
}
```

