```cpp
#include <map>
#include <mutex>

template <typename Key, typename Value>
class ThreadSafeMap {
public:
    void insert(const Key& key, const Value& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        map_[key] = value;
    }

    void erase(const Key& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        map_.erase(key);
    }

    Value get(const Key& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it != map_.end()) {
            return it->second;
        }
        // Handle key not found
        throw std::out_of_range("Key not found");
    }

    bool contains(const Key& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        return map_.find(key) != map_.end();
    }

private:
    std::map<Key, Value> map_;
    std::mutex mutex_;
};
```

In the solution, the `ThreadSafeMap` class is implemented using a `std::map` as the underlying data structure and a `std::mutex` for thread safety. The `insert`, `erase`, `get`, and `contains` methods are protected by a `std::lock_guard` to ensure mutual exclusion and prevent data corruption during concurrent access. This design guarantees that the map operations are thread-safe and can be used in a multi-threaded environment without causing race conditions.

