template <typename Duration>
class Timer {
public:
    Timer(const Duration& interval, const std::function<void()>& callback, bool autoStart = false)
        : interval_(interval), callback_(callback), autoStart_(autoStart), running_(false) {
        if (autoStart_) {
            start();
        }
    }

    void start() {
        running_ = true;
        thread_ = std::thread([this]() {
            while (running_) {
                std::this_thread::sleep_for(interval_);
                if (running_) {
                    callback_();
                }
            }
        });
    }

    void stop() {
        running_ = false;
        if (thread_.joinable()) {
            thread_.join();
        }
    }

    ~Timer() {
        stop();
    }

private:
    Duration interval_;
    std::function<void()> callback_;
    bool autoStart_;
    bool running_;
    std::thread thread_;
};

int main() {
