struct City {
    std::vector<City*> adj;
    std::unordered_map<City*, std::pair<int, int>> connectionInfo; // Stores distance and cost for each connection
};

std::unordered_map<int, City> constructCityGraph(std::vector<std::tuple<int, int, int, int>> connections) {
    std::unordered_map<int, City> cities;

    for (const auto& connection : connections) {
        int c1, c2, dist, cost;
        std::tie(c1, c2, dist, cost) = connection;

        cities[c1].adj.push_back(&cities[c2]);
        cities[c2].adj.push_back(&cities[c1]);

        cities[c1].connectionInfo[&cities[c2]] = std::make_pair(dist, cost);
        cities[c2].connectionInfo[&cities[c1]] = std::make_pair(dist, cost);
    }

    return cities;
}
