#include <queue>
#include <mutex>
#include <condition_variable>

template <typename T>
class ThreadSafeQueue {
public:
    void push(const T& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(value);
        lock.unlock();
        condition_.notify_one();
    }

    bool pop(T& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !queue_.empty(); });
        if (queue_.empty()) {
            return false;
        }
        value = queue_.front();
        queue_.pop();
        return true;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }

private:
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};
```

The `ThreadSafeQueue` class uses a `std::queue` to store the elements and ensures thread safety using a `std::mutex` and a `std::condition_variable`. The `push` method locks the mutex, adds the element to the queue, unlocks the mutex, and notifies any waiting threads. The `pop` method waits for the queue to become non-empty using the condition variable, then removes and returns the front element. The `empty` method simply checks if the queue is empty in a thread-safe manner.

Here's an example of a test case using Google Test framework to ensure the thread safety of the `ThreadSafeQueue` implementation:
```cpp
#include "gtest/gtest.h"
#include <thread>

TEST(ThreadSafeQueueTest, MultipleThreadsAccess) {
    ThreadSafeQueue<int> queue;
    const int numThreads = 4;
    const int numElements = 10000;

    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i) {
        threads.emplace_back([&queue, i, numElements] {
            for (int j = 0; j < numElements; ++j) {
                queue.push(i * numElements + j);
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    int sum = 0;
    for (int i = 0; i < numThreads * numElements; ++i) {
        int value;
        if (queue.pop(value)) {
            sum += value;
        }
    }

    ASSERT_EQ(sum, numThreads * numElements * (numThreads * numElements - 1) / 2);
}
```

