    arr.addElement(10);
    arr.addElement(20);
    arr.addElement(30);

    std::ofstream outputFile("output.bin", std::ios::binary);
    if (outputFile.is_open()) {
        arr.writeToStream(outputFile);
        outputFile.close();
        std::cout << "Elements written to output.bin in binary format." << std::endl;
    } else {
        std::cerr << "Unable to open output.bin for writing." << std::endl;
    }

    return 0;
}
